  1	import Foundation
  2	
  3	/// The warm loopback server process behind a local engine. Reuses a verified
  4	/// orphan of its own binary on the preferred port, otherwise spawns a child
  5	/// (on a private port when a foreign process holds the preferred one), then
  6	/// polls `GET /health` until it answers 200. A spawned child counts as ready
  7	/// only once it (or a process it started) is seen listening on the port:
  8	/// `lsof` cannot see another user's listener when the port is picked, and
  9	/// audio must never reach a squatter that answered in the child's place.
 10	///
 11	/// Callers overlap (warm-up, dictation, an engine switch), so one start runs
 12	/// at a time and the shared state sits behind a lock. A child that fails
 13	/// before it is ready sends the next start to a fresh port. `shutdown()`
 14	/// retires the server (app quit, engine switch): a start under way or begun
 15	/// later leaves nothing running and reports not ready.
 16	public final class ChildServer {
 17	    private let name: String
 18	    private let binaryPath: String
 19	    private let preferredPort: Int
 20	    private let session: URLSession
 21	    private let arguments: (Int) -> [String]
 22	    private let owns: (pid_t, Int) -> Bool
 23	    private let gate = StartGate()
 24	    private let lock = NSLock()
 25	    // Guarded by `lock`.
 26	    private var process: Process?
 27	    private var verified = false
 28	    private var currentPort: Int
 29	    private var avoidPreferredPort = false
 30	    private var retired = false
 31	
 32	    /// `arguments` builds the command line for the port the child binds.
 33	    /// `owns` tells whether a pid holds the port (tests replace the lsof check).
 34	    public init(name: String, binaryPath: String, port: Int, session: URLSession,
 35	                owns: @escaping (pid_t, Int) -> Bool = ChildServer.listens(pid:port:),
 36	                arguments: @escaping (Int) -> [String]) {
 37	        self.name = name
 38	        self.binaryPath = binaryPath
 39	        self.preferredPort = port
 40	        self.currentPort = port
 41	        self.session = session
 42	        self.owns = owns
 43	        self.arguments = arguments
 44	    }
 45	
 46	    deinit { shutdown() }
 47	
 48	    /// The port of the server last started or adopted.
 49	    public var port: Int { locked { currentPort } }
 50	
 51	    /// True once the server answers `/health`, polling up to `polls` times
 52	    /// (250 ms apart; a probe gives up after 1 s without data). When no child
 53	    /// of ours is running, `preflight` runs first (binary and model checks),
 54	    /// then the server is adopted or spawned. False on timeout, as soon as a
 55	    /// spawned child exits (a bad model never becomes ready), when another
 56	    /// process answered on the child's port (the child is stopped), or once
 57	    /// `shutdown()` has run.
 58	    public func ensureRunning(polls: Int, preflight: () throws -> Void) async throws -> Bool {
 59	        if await isVerifiedAndHealthy() { return true }
 60	        await gate.enter()
 61	        do {
 62	            let ready = try await start(polls: polls, preflight: preflight)
 63	            await gate.leave()
 64	            return ready
